+// API keys and role-based access control. Keys live in store.data.apiKeys as
+// { key, name, role }; roles are ordered viewer < cook < manager.
+import { AppError } from "../errors.js";
+
+/** Supported roles, from least to most privileged. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+/** Finds the API key record matching `token`, or throws AppError unauthorized. */
+export function authenticate(store, token) {
+  if (typeof token !== "string" || !token) throw new AppError("unauthorized");
+  const entry = (store.data.apiKeys ?? []).find((k) => k.key === token);
+  if (!entry) throw new AppError("unauthorized");
+  return entry;
+}
+
+/** Checks that `key` has at least `requiredRole`, or throws AppError forbidden. */
+export function authorize(key, requiredRole) {
+  const actual = ROLES.indexOf(key?.role);
+  const needed = ROLES.indexOf(requiredRole);
+  if (actual < 0 || needed < 0 || actual < needed) throw new AppError("forbidden");
+}
