@@ -0,0 +1,113 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { createApp } from "../src/http/server.js";
+import { t } from "../src/i18n/messages.js";
+import { app, auth, fresh, NOW, seed } from "./helpers.js";
+
+const viewerHeaders = auth("viewer");
+const cookHeaders = auth("cook");
+const managerHeaders = auth("manager");
+
+test("seed has one API key per role", () => {
+  const keys = seed().apiKeys;
+  assert.equal(keys.length, 3);
+  assert.deepEqual(keys.map((k) => k.role).sort(), ["cook", "manager", "viewer"]);
+  for (const k of keys) {
+    assert.ok(typeof k.key === "string" && k.key.length > 0);
+    assert.ok(typeof k.name === "string" && k.name.length > 0);
+  }
+});
+
+test("missing or unknown key answers 401 in error shape", async () => {
+  const { handle } = app();
+  for (const headers of [{}, { authorization: "Bearer wrong-key" }, { authorization: "Basic abc" }, { Authorization: "Bearer " }]) {
+    const res = await handle({ path: "/items", headers });
+    assert.equal(res.status, 401);
+    assert.equal(res.body.error.code, "unauthorized");
+    assert.ok(typeof res.body.error.message === "string" && res.body.error.message.length > 0);
+  }
+});
+
+test("viewer may only read (GET) and cannot read /audit", async () => {
+  const { handle } = app();
+  const ok = await handle({ path: "/items", headers: { Authorization: viewerHeaders.authorization } });
+  assert.equal(ok.status, 200);
+  for (const req of [
+    { method: "POST", path: "/recipes/1/cook", body: { portions: 1 } },
+    { method: "POST", path: "/batches/1/waste", body: { qty: 0.5 } },
+    { method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 4 } },
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } },
+    { method: "GET", path: "/audit" },
+  ]) {
+    const res = await handle({ ...req, headers: viewerHeaders });
+    assert.equal(res.status, 403);
+    assert.equal(res.body.error.code, "forbidden");
+    assert.ok(typeof res.body.error.message === "string" && res.body.error.message.length > 0);
+  }
+});
+
+test("cook may read, cook, waste, log temperatures and enter stock-take counts only", async () => {
+  const { handle } = app();
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: managerHeaders, body: { location: "dry" } })).body;
+
+  assert.equal((await handle({ path: "/items", headers: cookHeaders })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: cookHeaders, body: { portions: 4 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: cookHeaders, body: { qty: 0.5, reason: "bruised" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: cookHeaders, body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: cookHeaders, body: { batchId: 6, counted: 12 } })).status, 200);
+
+  for (const req of [
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } },
+    { method: "POST", path: "/orders/3/send" },
+    { method: "POST", path: "/stocktakes", body: { location: "fridge" } },
+    { method: "POST", path: `/stocktakes/${take.id}/finish` },
+    { method: "PUT", path: "/items/1/allergens", body: { allergens: [] } },
+    { method: "POST", path: "/dishes", body: { name: "Test", recipeId: 1, priceCents: 500 } },
+    { method: "POST", path: "/prices", body: { supplierId: 1, itemId: 1, priceCents: 190, validFrom: "2026-10-28" } },
+    { method: "POST", path: "/jobs/nightly" },
+    { method: "GET", path: "/audit" },
+  ]) {
+    const res = await handle({ ...req, headers: cookHeaders });
+    assert.equal(res.status, 403);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("audit records data-changing requests newest first for managers", async () => {
+  let time = NOW;
+  const store = fresh();
+  const handle = createApp(store, { clock: () => time });
+
+  await handle({ path: "/items", headers: viewerHeaders });
+  await handle({ method: "POST", path: "/orders", headers: viewerHeaders, body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } });
+
+  time = NOW + 1000;
+  await handle({ method: "POST", path: "/temperatures", headers: cookHeaders, body: { location: "fridge", celsius: 4 } });
+
+  time = NOW + 2000;
+  await handle({ method: "PUT", path: "/items/1/allergens", headers: managerHeaders, body: { allergens: ["celery"] } });
+
+  const auditRes = await handle({ path: "/audit", headers: managerHeaders });
+  assert.equal(auditRes.status, 200);
+  assert.equal(auditRes.body.length, 2);
+
+  assert.equal(auditRes.body[0].at, new Date(NOW + 2000).toISOString());
+  assert.equal(auditRes.body[0].keyName, "manager");
+  assert.equal(auditRes.body[0].method, "PUT");
+  assert.equal(auditRes.body[0].path, "/items/1/allergens");
+  assert.equal(auditRes.body[0].status, 200);
+
+  assert.equal(auditRes.body[1].at, new Date(NOW + 1000).toISOString());
+  assert.equal(auditRes.body[1].keyName, "cook");
+  assert.equal(auditRes.body[1].method, "POST");
+  assert.equal(auditRes.body[1].path, "/temperatures");
+  assert.equal(auditRes.body[1].status, 201);
+});
+
+test("auth error messages exist in English and Korean", () => {
+  for (const code of ["unauthorized", "forbidden"]) {
+    assert.notEqual(t(code, "en"), code);
+    assert.notEqual(t(code, "ko"), code);
+    assert.notEqual(t(code, "ko"), t(code, "en"));
+  }
+});
